<template><div v-if="item" class="page-pad"><a-breadcrumb><a-breadcrumb-item><a @click="$router.push('/deliveries')">交付</a></a-breadcrumb-item><a-breadcrumb-item>{{ item.name }}</a-breadcrumb-item></a-breadcrumb><div class="snapshot-head"><div><div class="mono text-secondary">{{ item.name }}</div><h2>{{ item.title }}</h2></div><a-tag color="green"><IconLock /> 已冻结</a-tag></div><a-descriptions bordered size="small" :column="2"><a-descriptions-item label="来源迭代">{{ item.milestone||'手动选择' }}</a-descriptions-item><a-descriptions-item label="创建人">{{ item.createdBy }}</a-descriptions-item><a-descriptions-item label="创建时间">{{ item.createdAt }}</a-descriptions-item><a-descriptions-item label="内容摘要"><span class="mono code-sm">{{ item.changesDigest }}</span></a-descriptions-item></a-descriptions><h3>冻结版本</h3><a-table :data="item.items" :pagination="false" :scroll="{x:680}"><template #columns><a-table-column title="需求" data-index="requirement" /><a-table-column title="项目" data-index="project" /><a-table-column title="版本"><template #cell="{ record }"><a @click="$router.push(`/projects/${record.project}/versions/${record.version}`)">{{ record.version }}</a></template></a-table-column></template></a-table></div></template>
<script setup>import{onMounted,ref,watch}from'vue';import{IconLock}from'@arco-design/web-vue/es/icon/index.js';import{api}from'../api';const props=defineProps({name:String}),item=ref(null);async function load(){item.value=await api.getSnapshot(props.name)}watch(()=>props.name,load);onMounted(load)</script>
<style scoped>.snapshot-head{display:flex;align-items:center;gap:16px;margin:20px 0}.snapshot-head>div{flex:1}.snapshot-head h2{margin:2px 0;font-size:var(--fl-fs-5)}h3{margin-top:24px;font-size:15px}</style>
